const TRANSITION = 15;

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

const NOISE_COMP = [
  0, 0.012, -0.008, 0.015, -0.005, 0.018, -0.010, 0.007, -0.013, 0.020,
  -0.006, 0.014, -0.009, 0.011, -0.016, 0.008, -0.004, 0.017, -0.011, 0.013,
  -0.007, 0.019, -0.012, 0.009, -0.015, 0.016, -0.003, 0.021, -0.008, 0.010,
  -0.014, 0.012, -0.006, 0.018, -0.010, 0.015, -0.009, 0.013, -0.017, 0.011,
  -0.005, 0.020, -0.008, 0.016, -0.012, 0.014, -0.007, 0.019, -0.011, 0.017,
  -0.004, 0.022, -0.009, 0.013, -0.016, 0.010, -0.006, 0.018, -0.013, 0.015,
  -0.008, 0.021, -0.005, 0.012, -0.017, 0.009, -0.014, 0.016, -0.003, 0.020,
