];

const NOISE_VIEW = [
  0, -0.010, 0.014, -0.007, 0.016, -0.012, 0.009, -0.018, 0.013, -0.005,
  0.017, -0.011, 0.008, -0.015, 0.019, -0.006, 0.012, -0.016, 0.010, -0.013,
  0.007, -0.020, 0.015, -0.009, 0.018, -0.004, 0.013, -0.017, 0.011, -0.008,
  0.016, -0.014, 0.006, -0.019, 0.012, -0.010, 0.017, -0.007, 0.014, -0.021,
  0.009, -0.015, 0.013, -0.011, 0.018, -0.006, 0.016, -0.012, 0.010, -0.019,
  0.008, -0.014, 0.017, -0.009, 0.013, -0.016, 0.005, -0.020, 0.011, -0.008,
  0.015, -0.013, 0.019, -0.007, 0.012, -0.017, 0.010, -0.014, 0.018, -0.006,
  0.016, -0.011, 0.009, -0.018, 0.014, -0.005, 0.020, -0.013, 0.008, -0.016,
  0.012, -0.010, 0.017, -0.015, 0.007, -0.019, 0.013, -0.009, 0.016, -0.012,
  0.011, -0.017, 0.014, -0.006, 0.020, -0.011, 0.015, -0.013, 0.009, -0.021,
];

function accumulateNoise(arr: number[], upTo: number): number {
  let sum = 0;
  for (let i = 0; i <= upTo && i < arr.length; i++) {
    sum += arr[i];
  }
  return sum;
}

function buildSmoothPath(
  getFn: (t: number, idx: number) => number,
  progress: number,
  paddingLeft: number,
  paddingTop: number,
  plotW: number,
  plotH: number,
  NUM_POINTS: number
): string {
  const count = Math.max(2, Math.floor(NUM_POINTS * progress));
  const points: [number, number][] = [];

  for (let i = 0; i <= count; i++) {
    const t = i / NUM_POINTS;
    const x = paddingLeft + t * plotW;
    const rawY = getFn(t, i);
    const y = paddingTop + (1 - Math.min(1, Math.max(0, rawY))) * plotH;
    points.push([x, y]);
  }

  if (points.length < 2) return "";

  let d = `M ${points[0][0]} ${points[0][1]}`;
  for (let i = 1; i < points.length; i++) {
    const prev = points[i - 1];
    const curr = points[i];
    const cpx = (prev[0] + curr[0]) / 2;
    d += ` C ${cpx} ${prev[1]}, ${cpx} ${curr[1]}, ${curr[0]} ${curr[1]}`;
  }
  return d;
}

function getCompetitorY(t: number, idx: number): number {
  const accNoise = accumulateNoise(NOISE_COMP, idx) * 0.5;

  if (t < 0.48) {
    const base = 0.42 + t * 0.04;
    const wave1 = Math.sin(t * Math.PI * 4.2) * 0.028;
    const wave2 = Math.sin(t * Math.PI * 7.1 + 1.2) * 0.014;
    return base + wave1 + wave2 + accNoise * 0.35;
  }

  const rise = (t - 0.48) / 0.52;
  const surge = Math.pow(rise, 0.35) * 0.44;
  const postNoise = accumulateNoise(NOISE_COMP, idx) * 0.18;
  return 0.44 + surge + postNoise;
}

function getViewerY(t: number, idx: number): number {
  const accNoise = accumulateNoise(NOISE_VIEW, idx) * 0.5;

  if (t < 0.48) {
    const base = 0.50 + t * 0.03;
    const wave1 = Math.sin(t * Math.PI * 4.2 + 1.8) * 0.026;
    const wave2 = Math.sin(t * Math.PI * 6.8 + 0.5) * 0.013;
    return base + wave1 + wave2 + accNoise * 0.35;
  }

  const fall = (t - 0.48) / 0.52;
  const drift = Math.pow(fall, 1.8) * 0.16;
  const postNoise = accumulateNoise(NOISE_VIEW, idx) * 0.20;
  return 0.514 - drift + postNoise;
}

const SCENE_DURATION = 380;

const GraphScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: FPS } = useVideoConfig();

  const drawProgress = interpolate(frame, [0, 140], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const eventProgress = spring({ frame, fps: FPS, delay: 64, config: { damping: 200 } });
  const labelsProgress = spring({ frame, fps: FPS, delay: 148, config: { damping: 200 } });

  const graphW = 3000;
  const graphH = 1300;
  const paddingLeft = 130;
  const paddingRight = 160;
  const paddingTop = 200;
  const paddingBottom = 110;
  const plotW = graphW - paddingLeft - paddingRight;
  const plotH = graphH - paddingTop - paddingBottom;
  const NUM_POINTS = 100;

  const competitorPath = buildSmoothPath(
    getCompetitorY, drawProgress, paddingLeft, paddingTop, plotW, plotH, NUM_POINTS
  );
  const viewerPath = buildSmoothPath(
    getViewerY, drawProgress, paddingLeft, paddingTop, plotW, plotH, NUM_POINTS
  );

  const eventX = paddingLeft + 0.48 * plotW;
  const markerLineH = interpolate(eventProgress, [0, 1], [0, plotH]);

  const tEnd = drawProgress;
  const idxEnd = Math.floor(tEnd * NUM_POINTS);
  const compEndX = paddingLeft + tEnd * plotW;
  const compEndY =
    paddingTop + (1 - Math.min(1, Math.max(0, getCompetitorY(tEnd, idxEnd)))) * plotH;
  const viewEndX = paddingLeft + tEnd * plotW;
  const viewEndY =
    paddingTop + (1 - Math.min(1, Math.max(0, getViewerY(tEnd, idxEnd)))) * plotH;

  const gridLines = [0.2, 0.4, 0.6, 0.8];
  const xLabels = ["12am", "2am", "4am", "6am", "8am", "10am", "12pm"];

  return (
    <AbsoluteFill
      style={{ fontFamily: "'Inter', sans-serif", backgroundColor: COLORS.bg }}
    >
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div style={{ width: graphW, position: "relative" }}>
          <svg width={graphW} height={graphH} style={{ overflow: "visible" }}>

            {/* Grid lines */}
            {gridLines.map((v) => {
              const y = paddingTop + (1 - v) * plotH;
              return (
                <g key={v}>
                  <line
                    x1={paddingLeft}
                    y1={y}
                    x2={paddingLeft + plotW}
                    y2={y}
                    stroke="rgba(255,255,255,0.12)"
                    strokeWidth={2}
                    strokeDasharray="12 8"
                  />
                  <text
                    x={paddingLeft - 18}
                    y={y + 8}
                    textAnchor="end"
                    fontSize={26}
                    fill="rgba(255,255,255,0.45)"
                    fontFamily="Inter, sans-serif"
                  >
                    {Math.round(v * 100)}%
                  </text>
                </g>
              );
            })}

            {/* X axis labels */}
            {xLabels.map((label, i) => {
              const x = paddingLeft + (i / (xLabels.length - 1)) * plotW;
              return (
                <text
                  key={label}
                  x={x}
                  y={paddingTop + plotH + 60}
                  textAnchor="middle"
                  fontSize={28}
                  fill="rgba(255,255,255,0.45)"
                  fontFamily="Inter, sans-serif"
                >
                  {label}
                </text>
              );
            })}

            {/* Axes */}
            <line
              x1={paddingLeft}
              y1={paddingTop}
              x2={paddingLeft}
              y2={paddingTop + plotH}
              stroke="rgba(255,255,255,0.30)"
              strokeWidth={3}
            />
            <line
              x1={paddingLeft}
              y1={paddingTop + plotH}
              x2={paddingLeft + plotW}
              y2={paddingTop + plotH}
              stroke="rgba(255,255,255,0.30)"
              strokeWidth={3}
            />

            {/* 2am vertical dashed marker */}
            {eventProgress > 0.01 && (
              <g>
                <line
                  x1={eventX}
                  y1={paddingTop + plotH}
                  x2={eventX}
                  y2={paddingTop + plotH - markerLineH}
                  stroke="rgba(255,255,255,0.55)"
                  strokeWidth={3}
                  strokeDasharray="14 7"
                />
                {/* 2AM label ABOVE the line */}
                <g opacity={eventProgress}>
                  <rect
                    x={eventX - 92}
                    y={paddingTop - 128}
                    width={184}
                    height={62}
                    rx={12}
                    fill="rgba(255,255,255,0.07)"
                    stroke="rgba(255,255,255,0.40)"
                    strokeWidth={2}
                  />
                  <line
                    x1={eventX}
                    y1={paddingTop - 66}
                    x2={eventX}
                    y2={paddingTop}
                    stroke="rgba(255,255,255,0.25)"
                    strokeWidth={2}
                  />
                  <text
                    x={eventX}
                    y={paddingTop - 82}
                    textAnchor="middle"
                    fontSize={30}
                    fontWeight="700"
                    fill="rgba(255,255,255,0.90)"
                    fontFamily="Inter, sans-serif"
                  >
                    2:00 AM
                  </text>
                </g>
              </g>
            )}

            {/* Competitor line — glow */}
            {drawProgress > 0.01 && (
              <>
                <path
                  d={competitorPath}
                  fill="none"
                  stroke={COLORS.competitor}
                  strokeWidth={28}
                  strokeOpacity={0.18}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
                <path
                  d={competitorPath}
                  fill="none"
                  stroke={COLORS.competitor}
                  strokeWidth={6}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </>
            )}

            {/* Viewer line — glow */}
            {drawProgress > 0.01 && (
              <>
                <path
                  d={viewerPath}
                  fill="none"
                  stroke={COLORS.viewer}
                  strokeWidth={28}
                  strokeOpacity={0.18}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
                <path
                  d={viewerPath}
                  fill="none"
                  stroke={COLORS.viewer}
                  strokeWidth={6}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </>
            )}

            {/* Traveling dots while drawing */}
            {drawProgress > 0.02 && drawProgress < 0.99 && (
              <>
                <circle cx={compEndX} cy={compEndY} r={12} fill={COLORS.competitor} opacity={0.95} />
                <circle cx={viewEndX} cy={viewEndY} r={12} fill={COLORS.viewer} opacity={0.95} />
              </>
            )}

            {/* Final end-point dots + inline labels */}
            {labelsProgress > 0.05 && (
              <>
                {/* Competitor dot + glow */}
                <circle
                  cx={compEndX}
                  cy={compEndY}
                  r={22}
                  fill={COLORS.competitor}
                  opacity={labelsProgress * 0.25}
                />
                <circle
                  cx={compEndX}
                  cy={compEndY}
                  r={13}
                  fill={COLORS.competitor}
                  opacity={labelsProgress}
                />
                {/* Competitor label */}
                <g
                  opacity={labelsProgress}
                  transform={`translate(${compEndX + 30}, ${compEndY - 36})`}
                >
                  <rect
                    x={0}
                    y={-46}
                    width={280}
                    height={62}
                    rx={14}
                    fill={`${COLORS.competitor}22`}
                    stroke={`${COLORS.competitor}88`}
                    strokeWidth={2}
                  />
                  <text
                    x={18}
                    y={-4}
                    fontSize={32}
                    fontWeight="700"
                    fill={COLORS.competitor}
                    fontFamily="Inter, sans-serif"
                  >
                    ↑ Competitor
                  </text>
                </g>

                {/* Viewer dot + glow */}
                <circle
                  cx={viewEndX}
                  cy={viewEndY}
                  r={22}
                  fill={COLORS.viewer}
                  opacity={labelsProgress * 0.25}
                />
                <circle
                  cx={viewEndX}
                  cy={viewEndY}
                  r={13}
                  fill={COLORS.viewer}
                  opacity={labelsProgress}
                />
                {/* Viewer label */}
                <g
                  opacity={labelsProgress}
                  transform={`translate(${viewEndX + 30}, ${viewEndY + 20})`}
                >
                  <rect
                    x={0}
                    y={-46}
                    width={160}
                    height={62}
                    rx={14}
                    fill={`${COLORS.viewer}22`}
                    stroke={`${COLORS.viewer}88`}
                    strokeWidth={2}
                  />
                  <text
                    x={18}
                    y={-4}
                    fontSize={32}
                    fontWeight="700"
                    fill={COLORS.viewer}
                    fontFamily="Inter, sans-serif"
                  >
                    ↓ You
                  </text>
                </g>
              </>
            )}
          </svg>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

const GRAPH_SCENE = SCENE_DURATION;

export const durationInFrames = GRAPH_SCENE + 25;

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={GRAPH_SCENE + TRANSITION}>
        <GraphScene />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />
      <TransitionSeries.Sequence durationInFrames={25}>
        <BlackScreen />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
